-- Neutral stat names in the data above -> this addon's stat keys.
local STAT_KEYS = {
	Agility = "AGILITY", Strength = "STRENGTH", Intellect = "INTELLECT", Spirit = "SPIRIT",
	Stamina = "STAMINA", AttackPower = "ATTACK_POWER", RangedAttackPower = "RANGED_ATTACK_POWER",
	SpellPower = "SPELL_POWER", CritRating = "CRIT", HitRating = "HIT", HasteRating = "HASTE",
	ArmorPenetration = "ARMOR_PENETRATION", Armor = "ARMOR", Dodge = "DODGE", Parry = "PARRY",
	Defense = "DEFENSE_SKILL", Mp5 = "MANA_REGENERATION",
}

-- The source weights carry no weapon DPS value. Weapon-based roles get one so weapon swaps
-- are judged on damage too; the size is in line with this addon's WotLK physical specs.
local WEAPON_DPS_BY_ROLE = { MELEE = 3, RANGED = 3, TANK = 1 }

-- Usability is decided from the character's own armor/weapon skills (see
-- class_can_use_standard_family in Item-ItemScore.lua), so every family is allowed here.
local ALL_ITEMTYPES = { CLOTH=1, LEATHER=1, MAIL=1, PLATE=1, SHIELD=1, BOW=1, CROSSBOW=1, DAGGER=1, FIST=1, GUN=1,
	MACE=1, TH_MACE=1, TH_POLE=1, TH_STAFF=1, SWORD=1, TH_SWORD=1, AXE=1, TH_AXE=1, WAND=1, THROWN=1, OFFHAND=1,
	MISCARM=1, JEWELERY=1 }

ItemScore.CoAClassSpecs = CoAClassSpec
ItemScore.CoAClassPrimaryStats = CoAClassPrimaryStats

local function BuildRule(spec)
	local stats = {}
	for neutral, weight in pairs(spec.weights or {}) do
		local key = STAT_KEYS[neutral]
		if key then stats[key] = weight end
	end
	local dps = 0
	for _, role in ipairs(spec.roles or {}) do dps = math.max(dps, WEAPON_DPS_BY_ROLE[role] or 0) end
	if dps > 0 then stats.DAMAGE_PER_SECOND = dps end
	stats.STAMINA = stats.STAMINA or 0.001 -- tie-breaker, as the stock builds do
	local itemtypes = {}
	for k, v in pairs(ALL_ITEMTYPES) do itemtypes[k] = v end
	return { name = spec.name, itemtypes = itemtypes, stats = stats, caps = {} }
end

-- Replace the generic CUSTOM builds with the player's CoA class specs. Safe to call again.
function ItemScore:ApplyCoAClassRules()
	if self.CoAClass then return true end
	local className, token = UnitClass("player")
	local data = token and CoAClassSpec[token]
	if not data or (self.rules[token] and token ~= "CUSTOM") then return false end

	local rules, names, sources = {}, {}, {}
	for i, spec in ipairs(data.specs) do
		rules[i] = BuildRule(spec)
		names[i] = spec.name
		sources[i] = { label = ("Conquest of Azeroth %s %s (coa-db class_spec_meta)"):format(data.name, spec.name), mode = "coa_class_spec" }
	end
	self.rules.CUSTOM = rules
	if self.RuleSources then self.RuleSources.CUSTOM = sources end
	if ZGV.SpecByNumber then ZGV.SpecByNumber.CUSTOM = names end
	self.CoAClass = { token = token, name = data.name or className, specs = data.specs }
	if self.Builds and self.SetData then self:SetData() end -- refresh build names if already built
	return true
end

-- The spec to start from: the first one built on the character's chosen primary stat.
function ItemScore:GetCoADefaultBuild()
	local coa = self.CoAClass
	if not coa then return 1 end
	local chosen
	if C_PrimaryStat and C_PrimaryStat.GetActivePrimaryStat then
		local ok, stat = pcall(C_PrimaryStat.GetActivePrimaryStat, C_PrimaryStat)
		if ok and stat then
			local ok2, _, _, _, name = pcall(C_PrimaryStat.GetPrimaryStatInfo, C_PrimaryStat, stat)
			if ok2 and type(name) == "string" then chosen = name:lower() end
		end
	end
	if chosen then
		for i, spec in ipairs(coa.specs) do
			if spec.primaryStat and spec.primaryStat:lower() == chosen then return i end
		end
	end
	return 1
end

-- Spec for /zdps, /ztank and /zheal, preferring one built on the chosen primary stat.
local ROLE_MATCH = {
	tank = { TANK = true },
	heal = { HEALER = true, SUPPORT = true },
	dps = { MELEE = true, RANGED = true, CASTER = true },
}
function ItemScore:GetCoARoleBuild(role)
	local coa, wanted = self.CoAClass, ROLE_MATCH[role]
	if not coa or not wanted then return nil end
	local preferred, first = self:GetCoADefaultBuild(), nil
	for i, spec in ipairs(coa.specs) do
		for _, r in ipairs(spec.roles or {}) do
			if wanted[r] then
				if i == preferred then return i end
				first = first or i
			end
		end
	end
	return first
end

ItemScore:ApplyCoAClassRules()
